<?php
/**
 * Access to recorded test vectors.
 *
 * @package BackupsForRestic\Tests
 */

declare( strict_types=1 );

namespace BackupsForRestic\Tests\Support;

use BackupsForRestic\Crypto\Cipher;
use BackupsForRestic\Crypto\MasterKey;
use BackupsForRestic\Crypto\SystemRandom;

/**
 * Loads vectors generated by Go, libsodium and the restic CLI (tests/Fixtures).
 */
final class Vectors {

	public const string RESTIC_VERSION = '0.19.1';

	public static function fixtures(): string {
		return dirname( __DIR__ ) . '/Fixtures';
	}

	/**
	 * @return array<mixed>
	 */
	public static function json( string $relative ): array {
		$data = json_decode( (string) file_get_contents( self::fixtures() . '/' . $relative ), true, 512, JSON_THROW_ON_ERROR );
		return is_array( $data ) ? $data : [];
	}

	public static function restic( string $relative ): string {
		return (string) file_get_contents( self::fixtures() . '/restic-' . self::RESTIC_VERSION . '/' . $relative );
	}

	/**
	 * @return list<string> Absolute paths.
	 */
	public static function restic_files( string $pattern ): array {
		$files = glob( self::fixtures() . '/restic-' . self::RESTIC_VERSION . '/raw/' . $pattern );
		return false === $files ? [] : $files;
	}

	public static function master_key(): MasterKey {
		return MasterKey::from_json( self::restic( 'masterkey.json' ) );
	}

	public static function cipher(): Cipher {
		return new Cipher( self::master_key(), new SystemRandom() );
	}

	/**
	 * Deterministic pseudo-random bytes: SHA-256(seed || counter) blocks, as in the Go generator.
	 */
	public static function hash_stream( string $seed, int $length ): string {
		$data = '';
		for ( $i = 0; 32 * $i < $length; $i++ ) {
			$data .= hash( 'sha256', $seed . pack( 'P', $i ), true );
		}
		return substr( $data, 0, $length );
	}
}
